/**
 * RIM-HSE certificate verification API
 * -------------------------------------
 * Runs on Cloudflare Workers (free tier). Replaces the old approach of
 * shipping the entire certificate database to every visitor's browser.
 *
 * The dataset below (CERTS) lives only in this server-side script — it is
 * never sent to the browser. The Worker accepts a certificate number,
 * normalises it, looks it up, and returns ONLY that one matching record
 * (or a generic "not found").
 *
 * Deploy instructions are in README-deploy.md in this same folder.
 */

// ---- 1. Allowed origins -----------------------------------------------
// Only these origins may call this API from a browser. Add/remove as
// needed. Keep this list tight — it's your main anti-scraping control.
const ALLOWED_ORIGINS = [
  "https://rim-hse.com",
  "https://www.rim-hse.com",
];

