// ---- 3. Helpers ----------------------------------------------------------
function normalize(s) {
  return (s || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
}

const KEY_INDEX = new Map(CERTS.map((rec) => [rec.key, rec]));

function corsHeaders(origin) {
  const allowed = ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
  return {
    "Access-Control-Allow-Origin": allowed,
    "Access-Control-Allow-Methods": "GET, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Vary": "Origin",
  };
}

function jsonResponse(body, status, origin) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json; charset=UTF-8",
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
      ...corsHeaders(origin),
    },
  });
}

// Only the fields the verification widget actually displays.
function publicFields(rec) {
  return {
    no: rec.no,
    holder: rec.holder,
    company: rec.company,
    type: rec.type,
    category: rec.category,
    issue: rec.issue,
    expiry: rec.expiry,
  };
}

// ---- 4. Request handler ---------------------------------------------------
export default {
  async fetch(request) {
    const origin = request.headers.get("Origin") || "";
    const url = new URL(request.url);

    // CORS preflight
    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: corsHeaders(origin) });
    }

    if (request.method !== "GET") {
      return jsonResponse({ error: "method_not_allowed" }, 405, origin);
    }

    if (url.pathname !== "/verify") {
      return jsonResponse({ error: "not_found" }, 404, origin);
    }

    const raw = url.searchParams.get("no") || "";

    // Basic input hygiene: reject absurdly long input before doing anything else.
    if (raw.length > 64) {
      return jsonResponse({ error: "invalid_input" }, 400, origin);
    }

    const key = normalize(raw);
    if (!key) {
      return jsonResponse({ error: "invalid_input" }, 400, origin);
    }

    const rec = KEY_INDEX.get(key);

    if (!rec) {
      // Deliberately generic — don't reveal anything about near-misses.
      return jsonResponse({ found: false }, 200, origin);
    }

    return jsonResponse({ found: true, record: publicFields(rec) }, 200, origin);
  },
};
